function erpPayload(l) {
  const f = BO.erp, v = Math.abs(l.value).toFixed(2), d = new Date(l.t).toISOString().slice(0, 10);
  if (f === "sap") return l.value > 0 ? { "A_SalesOrder": { SalesOrderType: "ZBND", SoldToParty: l.cp.toUpperCase().replace(/\s/g, "_"), PurchaseOrderByCustomer: l.id, to_Item: [{ Material: "COTA-" + (l.prog || "").toUpperCase(), RequestedQuantity: "1", NetAmount: v, ProfitCenter: "PC_BAND_VF" }] } } : { "A_SupplierInvoice": { Supplier: "MINU", DocumentDate: d, InvoiceGrossAmount: v, CostCenter: "CC_RECOMPENSAS", Reference: l.doc } };
  if (f === "totvs") return l.value > 0 ? { SC5: { C5_TIPO: "N", C5_CLIENTE: l.cp.slice(0, 6).toUpperCase(), C5_EMISSAO: d.replace(/-/g, ""), C5_XINIC: l.id }, SC6: [{ C6_PRODUTO: "COTA" + (l.prog || "").toUpperCase(), C6_QTDVEN: 1, C6_VALOR: +v, C6_CC: "BANDVF" }] } : { SE2: { E2_FORNECE: "MINU01", E2_EMISSAO: d.replace(/-/g, ""), E2_VALOR: +v, E2_CCD: "RECOMP", E2_HIST: l.desc.slice(0, 40) } };
  if (f === "oracle") return l.value > 0 ? { recordType: "salesOrder", entity: l.cp, tranDate: d, department: "Band x VF", item: [{ item: "COTA-" + l.prog, amount: +v }], memo: l.id } : { recordType: "vendorBill", entity: "Minu", tranDate: d, department: "Recompensas", amount: +v, memo: l.doc };
  return { id: l.id, type: l.value > 0 ? "receivable" : "payable", counterparty: l.cp, date: d, amount: +v, currency: "BRL", property: l.prog, document: l.doc, partnership: "BAND_VF_5050" };
}
